impl LiveRegister for App {
    fn live_register(cx: &mut Cx) {
        makepad_widgets::live_design(cx);
        crawrad_runtime_makepad::live_design(cx);
    }
}

impl MatchEvent for App {
    fn handle_actions(&mut self, cx: &mut Cx, actions: &Actions) {
        crawrad_runtime_makepad::dialogs::handle_dialog_actions(cx, &self.ui.view(id!(crawrad_message_dialog)), actions);
        if self.form.edit1.enabled && let Some(_val) = self.ui.text_input(id!(edit1)).changed(actions) {
            let _val = crawrad_runtime_makepad::memo::hold_to(cx, &self.ui.text_input(id!(edit1)), &_val, self.form.edit1.max_length).unwrap_or(_val);
            let _val = crawrad_runtime_makepad::edit::hold_case(cx, &self.ui.text_input(id!(edit1)), &_val, &self.form.edit1.char_case).unwrap_or(_val);
            self.form.edit1.text = _val;
        }
        if self.form.button1.enabled && self.ui.button(id!(button1)).clicked(actions) {
            self.form.button1_click();
        }
        self.sync_ui(cx);
    }
}

impl AppMain for App {
    fn handle_event(&mut self, cx: &mut Cx, event: &Event) {
        if self.initial_sync {
            self.initial_sync = false;
            self.sync_ui(cx);
        }
        if crawrad_runtime_makepad::dialogs::handle_dialog_key(cx, &self.ui.view(id!(crawrad_message_dialog)), event) {
            // A key answered the dialog: run the action pass now, so a
            // MessageDialog's answer reaches `modal_result`/`OnClose`
            self.handle_actions(cx, &[]);
            return;
        }
        // Tab walks the controls in TabOrder; the control that
        // takes the focus does not take the key as well.
        let crawrad_tab = [
            // TabOrder &[0]
            (self.form.edit1.visible && self.form.edit1.enabled, false, self.ui.widget(id!(edit1))),
            // TabOrder &[1]
            (self.form.button1.visible && self.form.button1.enabled, false, self.ui.widget(id!(button1))),
        ];
        if crawrad_runtime_makepad::tab_order::tab_key(cx, &crawrad_tab, event) {
            return;
        }
        let text_box_key = crawrad_runtime_makepad::keys::text_box_enter(cx, &[], &[self.ui.widget(id!(edit1))], event);
        let event = text_box_key.as_ref().unwrap_or(event);
        // ---- THE CONTROLS' POINTER, FOCUS AND KEYBOARD EVENTS --
        // Observed, not taken: the widgets still get this event below.
        {
            let mut rects = Vec::new();
            if self.form.label1.enabled { rects.push((0usize, self.ui.widget(id!(label1)).area().rect(cx))); }
            if self.form.edit1.enabled { rects.push((1usize, self.ui.widget(id!(edit1)).area().rect(cx))); }
            if self.form.button1.enabled { rects.push((2usize, self.ui.widget(id!(button1)).area().rect(cx))); }
            if self.form.label2.enabled { rects.push((3usize, self.ui.widget(id!(label2)).area().rect(cx))); }
            let hits = self.crawrad_pointer.route(event, &rects);
            let mut called = false;
            for hit in &hits {
                match (hit.control, hit.kind) {
                (0, CrawradPointer::Enter) => {
                    if CRAWRAD_FORM_SHOW_HINT && self.form.label1.show_hint && !self.form.label1.hint.is_empty() {
                        self.ui.tooltip(id!(crawrad_tooltip)).show_with_options(cx, hit.at + dvec2(12.0, 20.0), &self.form.label1.hint);
                    };
                    called = true;
                }
                (0, CrawradPointer::Leave) => {
                    self.ui.tooltip(id!(crawrad_tooltip)).hide(cx);
                    called = true;
                }
                (0, CrawradPointer::Down) => {
                    self.ui.tooltip(id!(crawrad_tooltip)).hide(cx);
                    called = true;
                }
                (0, CrawradPointer::Click) => {
                    match self.form.label1.focus_control.as_str() {
                        "edit1" => self.ui.widget(id!(edit1)).set_key_focus(cx),
                        "button1" => self.ui.widget(id!(button1)).set_key_focus(cx),
                        _ => {}
                    };
                    called = true;
                }
                (1, CrawradPointer::Enter) => {
                    if CRAWRAD_FORM_SHOW_HINT && self.form.edit1.show_hint && !self.form.edit1.hint.is_empty() {
                        self.ui.tooltip(id!(crawrad_tooltip)).show_with_options(cx, hit.at + dvec2(12.0, 20.0), &self.form.edit1.hint);
                    };
                    called = true;
                }
                (1, CrawradPointer::Leave) => {
                    self.ui.tooltip(id!(crawrad_tooltip)).hide(cx);
                    called = true;
                }
                (1, CrawradPointer::Down) => {
                    self.ui.tooltip(id!(crawrad_tooltip)).hide(cx);
                    called = true;
                }
                (2, CrawradPointer::Enter) => {
                    if CRAWRAD_FORM_SHOW_HINT && self.form.button1.show_hint && !self.form.button1.hint.is_empty() {
                        self.ui.tooltip(id!(crawrad_tooltip)).show_with_options(cx, hit.at + dvec2(12.0, 20.0), &self.form.button1.hint);
                    };
                    called = true;
                }
                (2, CrawradPointer::Leave) => {
                    self.ui.tooltip(id!(crawrad_tooltip)).hide(cx);
                    called = true;
                }
                (2, CrawradPointer::Down) => {
                    self.ui.tooltip(id!(crawrad_tooltip)).hide(cx);
                    called = true;
                }
                (3, CrawradPointer::Enter) => {
                    if CRAWRAD_FORM_SHOW_HINT && self.form.label2.show_hint && !self.form.label2.hint.is_empty() {
                        self.ui.tooltip(id!(crawrad_tooltip)).show_with_options(cx, hit.at + dvec2(12.0, 20.0), &self.form.label2.hint);
                    };
                    called = true;
                }
                (3, CrawradPointer::Leave) => {
                    self.ui.tooltip(id!(crawrad_tooltip)).hide(cx);
                    called = true;
                }
                (3, CrawradPointer::Down) => {
                    self.ui.tooltip(id!(crawrad_tooltip)).hide(cx);
                    called = true;
                }
                (3, CrawradPointer::Click) => {
                    match self.form.label2.focus_control.as_str() {
                        "edit1" => self.ui.widget(id!(edit1)).set_key_focus(cx),
                        "button1" => self.ui.widget(id!(button1)).set_key_focus(cx),
                        _ => {}
                    };
                    called = true;
                }
                _ => {}
                }
            }
            if called {
                self.sync_ui(cx);
            }
        }
        self.match_event(cx, event);
        self.ui.handle_event(cx, event, &mut Scope::empty());
        // #667: the Cursor of the control under the pointer, or the form's
        if let Event::MouseMove(e) = event {
            let mut cursor: Option<&str> = None;
            if cursor.is_none() && self.form.label2.visible && self.form.label2.enabled && self.ui.widget(id!(label2)).area().rect(cx).contains(e.abs) {
                cursor = Some(match self.form.label2.cursor { Cursor::Default => "arrow", c => c.as_str() });
            }
            if cursor.is_none() && self.form.button1.visible && self.form.button1.enabled && self.ui.widget(id!(button1)).area().rect(cx).contains(e.abs) {
                cursor = Some(match self.form.button1.cursor { Cursor::Default => "hand", c => c.as_str() });
            }
            if cursor.is_none() && self.form.edit1.visible && self.form.edit1.enabled && self.ui.widget(id!(edit1)).area().rect(cx).contains(e.abs) {
                cursor = Some(match self.form.edit1.cursor { Cursor::Default => "text", c => c.as_str() });
            }
            if cursor.is_none() && self.form.label1.visible && self.form.label1.enabled && self.ui.widget(id!(label1)).area().rect(cx).contains(e.abs) {
                cursor = Some(match self.form.label1.cursor { Cursor::Default => "arrow", c => c.as_str() });
            }
            crawrad_runtime_makepad::cursor::show(cx, cursor.unwrap_or("arrow"));
        }
    }
}

app_main!(App);

/// The form's `ShowHint`: off, no control on it shows its hint.
         const CRAWRAD_FORM_SHOW_HINT: bool = true;
